def short(t,n=92):
    t=t.replace(' [Электронный ресурс]','').replace(' [Электронное издание]','').strip(' .')
    t=re.sub(r'органов внутренних дел|органами внутренних дел|органах внутренних дел','ОВД',t)
    t=t.replace('Российской Федерации','РФ').replace('участковых уполномоченных полиции','УУП').replace('участкового уполномоченного полиции','УУП').replace('участковым уполномоченным полиции','УУП').replace('участковыми уполномоченными полиции','УУП')
    t=t.replace('административных правонарушениях','АП').replace('административных правонарушений','АП').replace('общественного порядка','ОП').replace('общественной безопасности','ОБ')
    t=t.replace('­ ','').replace('­','')
    if len(t)>n: t=t[:n].rsplit(' ',1)[0].rstrip(' ,(-')+'…'
    return t
def auth(resp):
    r=re.sub(r'^(сост\.|составители|редкол\.|отв\. ред\. ?|под ред\.|под общ\. ред\.)\s*:?\s*','',resp.replace('- ','')).strip()
    r=re.split(r'\s*;|\. – |\. — | Электрон',r)[0]
    names=re.findall(r'((?:[А-ЯЁ]\.\s?){1,2})\s?([А-ЯЁ][а-яё]+(?:-[А-ЯЁ][а-яё]+)?)|([А-ЯЁ][а-яё]+)\s((?:[А-ЯЁ]\.\s?){1,2})',r)
    sur=[(a[1] or a[2]) for a in names]
    if not sur: return ''
    if len(sur)>2 or 'и др' in r: return sur[0]+' и др.'
    return ', '.join(sur)
