def cat(kind,year):
    k=kind.lower()
    if re.search(r'аналитическ',k): return 5
    if re.search(r'монограф|сборник|материалы|научно-практ|научно-метод',k): return 4
    return 3
def expand(s):
    out=set()
    for p in re.findall(r'\d+(?:-\d+)?',s):
        a=p.split('-'); out.update(range(int(a[0]),int(a[-1])+1))
    return sorted(out)
